import numpy as np

def solve():
    # Triples (u, v, w) such that u=x+y, v=y+z, w=z+x for x,y,z in [0,9]
    # These are the same as the possible questions (A, B, C)
    triples = []
    for x in range(10):
        for y in range(10):
            for z in range(10):
                triples.append((x+y, y+z, z+x))

    num_p = len(triples)
    triples = np.array(triples)

    # Pre-calculate distances
    dists = np.zeros((num_p, num_p), dtype=int)
    for q_idx in range(num_p):
        A, B, C = triples[q_idx]
        dists[q_idx] = np.sum(np.abs(triples - [A, B, C]), axis=1)

    # Use a cache for distinguishability
    memo_distinguishable = {}

    def is_distinguishable(s1_indices):
        s1_tuple = tuple(sorted(s1_indices))
        if s1_tuple in memo_distinguishable:
            return memo_distinguishable[s1_tuple]

        if len(s1_tuple) <= 1:
            memo_distinguishable[s1_tuple] = True
            return True

        for q2_idx in range(num_p):
            v2_values = set()
            is_unique = True
            for p_idx in s1_tuple:
                v2 = dists[q2_idx, p_idx]
                if v2 in v2_values:
                    is_unique = False
                    break
                v2_values.add(v2)

            if is_unique:
                memo_distinguishable[s1_tuple] = True
                return True

        memo_distinguishable[s1_tuple] = False
        return False

    # Try each q1
    for q1_idx in range(num_p):
        v1_to_s1 = {}
        for p_idx in range(num_p):
            v1 = dists[q1_idx, p_idx]
            if v1 not in v1_to_s1:
                v1_to_s1[v1] = []
            v1_to_s1[v1].append(p_idx)

        all_distinguishable = True
        for v1 in v1_to_s1:
            if not is_distinguishable(v1_to_s1[v1]):
                all_distinguishable = False
                break

        if all_distinguishable:
            return 2

    return 3

