Bad = [[0] * N for _ in range(N)]
for i in range(N):
    for j in range(i + 1, N):
        mask = 0
        for k in range(N):
            if dists[i, k] == dists[j, k]:
                mask |= (1 << k)
        Bad[i][j] = mask
        Bad[j][i] = mask

def solve():
    for q1_idx in range(N):
        groups1 = {}
        for i in range(N):
            d1 = dists[q1_idx, i]
            if d1 not in groups1:
                groups1[d1] = []
            groups1[d1].append(i)

        possible_for_all_q1_results = True
        for d1 in groups1:
            group1 = groups1[d1]
            if len(group1) <= 2:
                continue

            # For this group1, can we find a Q2?
            found_Q2 = False
            for q2_idx in range(N):
                subgroups2 = {}
                for p_idx in group1:
                    d2 = dists[q2_idx, p_idx]
                    if d2 not in subgroups2:
                        subgroups2[d2] = []
                    subgroups2[d2].append(p_idx)

                possible_for_all_subgroups2 = True
                for d2 in subgroups2:
                    subgroup2 = subgroups2[d2]
                    if len(subgroup2) <= 2:
                        continue

                    # For this subgroup2, can we find a Q3?
                    found_Q3 = False
                    combined_bad3 = 0
                    for i in range(len(subgroup2)):
                        for j in range(i + 1, len(subgroup2)):
                            combined_bad3 |= Bad[subgroup2[i]][subgroup2[j]]

                    if combined_bad3 != (1 << N) - 1:
                        found_Q3 = True
                        break
                    else:
                        possible_for_all_subgroups2 = False
                        break

                if possible_for_all_subgroups2:
                    found_Q2 = True
                    break

            if not found_Q2:
                possible_for_all_q1_results = False
                break

        if possible_for_all_q1_results:
            return True, q1_idx
    return False, None

result, q1_idx = solve()
print(f"Result for 3 questions: {result}")

